INSERT INTO public.operacao_registros (id,company_id,frente_id,etapa_id,author_profile_id,kind,text,status,created_at) VALUES ('151303ad-7045-4634-974a-12bd2d88f963','7d831e59-6e82-427b-95a0-64904aae5dd2','d78ae0c7-d0a1-482c-af3a-ce6c32ef4b72',NULL,'d8e502f7-9ceb-4dae-bd73-7291832d0d6f','evolucao','Dia 1 de montagem (18/05). Estado inicial do recinto e posicionamento dos contentores. Pendências da Câmara: troncos de árvore e traves de râguebi por retirar do relvado às 08h08.',NULL,'2026-05-18 20:00:00+01');
INSERT INTO public.operacao_registros (id,company_id,frente_id,etapa_id,author_profile_id,kind,text,status,created_at) VALUES ('56ab1de0-4b6e-4b9e-a3c4-04f4ea66ac7c','7d831e59-6e82-427b-95a0-64904aae5dd2','329912ab-ad47-47b9-9f75-3103b2481401',NULL,'d8e502f7-9ceb-4dae-bd73-7291832d0d6f','evolucao','Dia 1 de montagem (18/05). Início da montagem do palco (1,70m de altura) e finalização do piso ao fim do dia.',NULL,'2026-05-18 20:00:00+01');
INSERT INTO public.operacao_registros (id,company_id,frente_id,etapa_id,author_profile_id,kind,text,status,created_at) VALUES ('b735a8b5-5b96-4ad8-8784-ca639fe9b033','7d831e59-6e82-427b-95a0-64904aae5dd2','bd4d0cd9-1846-4816-a567-170ad7abb029',NULL,'d8e502f7-9ceb-4dae-bd73-7291832d0d6f','evolucao','Dia 1 de montagem (18/05). Entrega de sanitários: 13 químicos e 7 casas de banho de madeira; posicionamento junto aos camarins. Ocorrência: ar-condicionado avariado na entrega.',NULL,'2026-05-18 20:00:00+01');
INSERT INTO public.operacao_registros (id,company_id,frente_id,etapa_id,author_profile_id,kind,text,status,created_at) VALUES ('5977ebe3-69e7-42b2-9ff8-e01b9256963c','7d831e59-6e82-427b-95a0-64904aae5dd2','329912ab-ad47-47b9-9f75-3103b2481401',NULL,'d8e502f7-9ceb-4dae-bd73-7291832d0d6f','evolucao','Dia 2 de montagem (19/05). Continuação do palco pela IRMARFER e montagem da estrutura de cobertura, finalizada ao fim do dia. Troca dos carpetes da tenda VIP.',NULL,'2026-05-19 20:00:00+01');
INSERT INTO public.operacao_registros (id,company_id,frente_id,etapa_id,author_profile_id,kind,text,status,created_at) VALUES ('fa3510ea-69ec-4fdc-a783-b4aed3a1b6c5','7d831e59-6e82-427b-95a0-64904aae5dd2','575dbffd-5e4f-4f75-a3db-e990399907ed',NULL,'d8e502f7-9ceb-4dae-bd73-7291832d0d6f','evolucao','Dia 2 de montagem (19/05). Energização dos contentores de camarim atrás do palco e posicionamento de contentores de camarim no estacionamento. Ocorrência: grama seca no espaço das casas de banho.',NULL,'2026-05-19 20:00:00+01');
INSERT INTO public.operacao_registros (id,company_id,frente_id,etapa_id,author_profile_id,kind,text,status,created_at) VALUES ('edc14008-2799-4358-86d8-b70f956956ef','7d831e59-6e82-427b-95a0-64904aae5dd2','329912ab-ad47-47b9-9f75-3103b2481401',NULL,'d8e502f7-9ceb-4dae-bd73-7291832d0d6f','evolucao','Dia 3 de montagem (20/05). Finalização da cobertura do palco. Ocorrência: empilhadeira da IRMARFER atolada, atividades encerradas sem comunicação prévia.',NULL,'2026-05-20 20:00:00+01');
INSERT INTO public.operacao_registros (id,company_id,frente_id,etapa_id,author_profile_id,kind,text,status,created_at) VALUES ('be814e6b-7703-486a-b635-c0d8adafdb67','7d831e59-6e82-427b-95a0-64904aae5dd2','bd4d0cd9-1846-4816-a567-170ad7abb029',NULL,'d8e502f7-9ceb-4dae-bd73-7291832d0d6f','evolucao','Dia 3 de montagem (20/05). Ocorrências: contentores da VENDAP não retirados pela Câmara, 3h30 de atraso na operação; portas das casas de banho em contentor avariadas, com trancas improvisadas; dificuldades com operador e motorista na movimentação dos contentores.',NULL,'2026-05-20 20:00:00+01');
INSERT INTO public.operacao_registros (id,company_id,frente_id,etapa_id,author_profile_id,kind,text,status,created_at) VALUES ('597fd0d9-a470-4b6e-9e09-5fb6ba57e30c','7d831e59-6e82-427b-95a0-64904aae5dd2','329912ab-ad47-47b9-9f75-3103b2481401',NULL,'d8e502f7-9ceb-4dae-bd73-7291832d0d6f','evolucao','Dia 4 de montagem (21/05). Posicionamento da regie (house mix), continuação do palco, entrega da plataforma elevatória 26M, montagem das tendas de Backline e torre de LED. Ocorrência: erro de comunicação da IRMARFER nas lonas das tendas.',NULL,'2026-05-21 20:00:00+01');
INSERT INTO public.operacao_registros (id,company_id,frente_id,etapa_id,author_profile_id,kind,text,status,created_at) VALUES ('21369faa-c63e-403f-ad59-f0072259cd5c','7d831e59-6e82-427b-95a0-64904aae5dd2','329912ab-ad47-47b9-9f75-3103b2481401',NULL,'d8e502f7-9ceb-4dae-bd73-7291832d0d6f','evolucao','Dia 5 de montagem (22/05). Finalização das torres de LED e PA, montagem da regie, recolha de 66 baias. Palco 100% concluído, serviço da IRMARFER finalizado. Ocorrências: vedação caída com o vento e recolocada; poça de água junto à regie após teste de rega.',NULL,'2026-05-22 20:00:00+01');
